(npx vite preview --port 4173 --strictPort > /tmp/viz-shot/preview.log 2>&1 &) ; sleep 4; cat > /tmp/viz-shot/shot.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch({ args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1040, height: 620 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:4173/', { waitUntil: 'networkidle' });
await page.screenshot({ path: '/tmp/viz-shot/light.png' });
// hover the 8th point to check tooltip
const svg = await page.locator('svg').first().boundingBox();
await page.mouse.move(svg.x + svg.width * 0.62, svg.y + 120);
await page.waitForTimeout(150);
await page.screenshot({ path: '/tmp/viz-shot/light-hover.png' });
console.log('errors:', JSON.stringify(errors));
await browser.close();
EOF
cd /tmp/viz-shot && timeout 120 node shot.mjs; echo "exit=$?"

