cd /tmp/viz-shot && cat > shot2.mjs <<'EOF'
import { chromium } from 'playwright';
const [,, url, out, hoverX] = process.argv;
const browser = await chromium.launch({ executablePath: '/home/node/.cache/ms-playwright/chromium_headless_shell-1148/chrome-linux/headless_shell', args: ['--no-sandbox', '--disable-dev-shm-usage', '--disable-gpu'] });
const page = await browser.newPage({ viewport: { width: 1040, height: 460 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto(url, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(300);
if (hoverX) {
  const svg = await page.locator('svg').first().boundingBox();
  await page.mouse.move(svg.x + svg.width * Number(hoverX), svg.y + 120);
  await page.waitForTimeout(150);
}
await page.screenshot({ path: out });
const bg = await page.evaluate(() => getComputedStyle(document.querySelector('.g-root')).backgroundColor);
const txt = await page.evaluate(() => getComputedStyle(document.querySelector('figcaption div')).color);
console.log(JSON.stringify({ out, rootBg: bg, titleColor: txt, errors }));
await browser.close();
EOF
